for (const p of pages) {
  result[p.name] = { id: p.id, childrenCount: p.children.length };
  if (p.name.includes("Start Here")) {
    // Collect all text from Start Here
    const texts = [];
    function walk(node) {
      if (node.type === 'TEXT') {
        texts.push({ name: node.name, text: node.characters });
      }
      if ('children' in node) {
        for (const child of node.children) walk(child);
      }
    }
    walk(p);
    result[p.name].texts = texts;
  }
}
return result;

