  if (!node) return null;
  return {
    id: node.id,
    name: node.name,
    type: node.type,
    width: node.width,
    height: node.height,
    children: 'children' in node ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type, characters: c.type === 'TEXT' ? c.characters : undefined })) : []
  };
}

